export const CARRIER = {};
export const SHENG = { "木":"火","火":"土","土":"金","金":"水","水":"木" };
export const KE = { "木":"土","土":"水","水":"火","火":"金","金":"木" };
export function judgeRelation(P, Q) {
  if (P === Q) return "自对";
  if (SHENG[P] === Q) return "相生";
  if (SHENG[Q] === P) return "被生";
  if (KE[P] === Q) return "相克";
  if (KE[Q] === P) return "被克";
  return "未知";
}
